          </li>
        ))}
      </ul>
    </section>
  );
}

import { useState } from 'react';

const INICIALES = [
  { id: 1, texto: 'Aprender useState', hecha: true },
  { id: 2, texto: 'Dominar las listas', hecha: false },
  { id: 3, texto: 'Vencer al boss', hecha: false },
];

export default function App() {
  const [tareas, setTareas] = useState(INICIALES);

  const pendientes = tareas.filter((tarea) => !tarea.hecha).length;

  function alternar(id) {
    setTareas(
      tareas.map((tarea) =>
        tarea.id === id ? { ...tarea, hecha: !tarea.hecha } : tarea,
      ),
    );
  }

  return (
    <section>
      <h1>Mis tareas</h1>

      <p className="pendientes">Quedan {pendientes}</p>

      <ul>
        {tareas.map((tarea) => (
          <li
            key={tarea.id}
            className={`tarea ${tarea.hecha ? 'hecha' : ''}`}
            onClick={() => alternar(tarea.id)}
          >
            {tarea.texto}
          </li>
        ))}
      </ul>
    </section>
  );
}

